	hasSearch = true,
	chapterType = ChapterType.HTML,
	startIndex = 1,
	listings = LISTINGS,
	searchFilters = {},
	settings = {},

	parseNovel = parseNovel,
	getPassage = getPassage,
	search = search,
	isSearchIncrementing = false,
	updateSetting = function(id, value) end,
	shrinkURL = function(url)
		local escaped = baseURL:gsub("([%^%$%(%)%%%.%[%]%*%+%-%?])", "%%%1")
		return (url:gsub("^" .. escaped, ""))
	end,
	expandURL = function(url)
		return absoluteURL(url)
	end
}
